/**
 * Prune e2e/__screenshots__ of files no spec writes any more.
 *
 * The documentation screenshots are regenerated by every e2e run, so a renamed
 * or removed shot would otherwise stay in git forever. This script works out
 * the set of files the specs can produce and deletes everything else in the
 * folder (it never touches anything outside it).
 *
 * Writers it knows about:
 *   - e2e/visual.spec.ts      shoot(page, p, 'NN-name'[, { full: true }]) for every project
 *                             in the config (a `-full` file only on the projects the spec
 *                             keeps it for, see FULL_PROJECTS in the spec)
 *   - e2e/responsive.spec.ts  responsive-<project>-<viewport>.png for every VIEWPORTS name,
 *                             on the projects that run that spec (config testIgnore)
 *   - any other spec          a literal `<name>.png` string is kept as written
 * A spec that mentions the screenshot folder in a way this script cannot read
 * is reported as a warning so the table above gets extended.
 *
 * Out of scope, on purpose:
 *   - Mini-game specs (e2e/games/*.spec.ts) are not scanned. Games write their
 *     screenshots with shootGame to docs/games/img/<id>-<name>.png, which this
 *     script never reads or deletes (src/games/registry.test.ts budgets them).
 *   - Sub-folders of e2e/__screenshots__ are left alone.
 *
 * Usage:
 *   node scripts/screenshots-dedupe.mjs            delete stale files
 *   node scripts/screenshots-dedupe.mjs --dry-run  list them only
 *   node scripts/screenshots-dedupe.mjs --check    list them and exit 1 if any (for CI)
 */
import { readdirSync, readFileSync, rmSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const shots = join(root, 'e2e', '__screenshots__');
const specDir = join(root, 'e2e');

const args = new Set(process.argv.slice(2));
const check = args.has('--check');
const dryRun = check || args.has('--dry-run');

const read = (path) => readFileSync(path, 'utf8');

/** Project names declared in playwright.config.ts, and which ones skip a spec. */
function readProjects() {
  const config = read(join(root, 'playwright.config.ts'));
  const projectsBlock = config.slice(config.indexOf('projects:'));
  const projects = [...projectsBlock.matchAll(/name:\s*'([^']+)'/g)].map((m) => m[1]);
  // A project block with `testIgnore: /spec-name/` does not run that spec.
  const ignores = new Map();
  for (const name of projects) {
    const start = projectsBlock.indexOf(`name: '${name}'`);
    const next = projects.map((p) => projectsBlock.indexOf(`name: '${p}'`)).filter((i) => i > start);
    const block = projectsBlock.slice(start, next.length ? Math.min(...next) : undefined);
    const m = block.match(/testIgnore:\s*\[?([^\]\n]+)/);
    ignores.set(name, m ? m[1] : '');
  }
  return { projects, runs: (project, spec) => !ignores.get(project)?.includes(spec) };
}

const { projects, runs } = readProjects();
const expected = new Set();
const warnings = [];

// Top-level specs only: e2e/games/ (mini games) is out of scope, see above.
for (const file of readdirSync(specDir).filter((f) => f.endsWith('.spec.ts') && statSync(join(specDir, f)).isFile())) {
  const text = read(join(specDir, file));
  const base = file.replace(/\.spec\.ts$/, '');
  const active = projects.filter((p) => runs(p, base));
  let understood = false;

  if (file === 'visual.spec.ts') {
    understood = true;
    const fullProjects = (text.match(/FULL_PROJECTS\s*=\s*\[([^\]]*)\]/)?.[1] ?? '')
      .split(',')
      .map((s) => s.trim().replace(/^['"]|['"]$/g, ''))
      .filter(Boolean);
    for (const m of text.matchAll(/shoot\(\s*page\s*,\s*(?:p|project)\s*,\s*'([^']+)'(?:\s*,\s*\{[^}]*full:\s*true)?/g)) {
      for (const project of active) {
        expected.add(`${project}-${m[1]}.png`);
        if (m[0].includes('full: true') && fullProjects.includes(project)) expected.add(`${project}-${m[1]}-full.png`);
      }
    }
  }

  if (file === 'responsive.spec.ts') {
    understood = true;
    const names = [...(text.match(/const VIEWPORTS[\s\S]*?\];/)?.[0] ?? '').matchAll(/name:\s*'([^']+)'/g)].map((m) => m[1]);
    for (const project of active) for (const name of names) expected.add(`responsive-${project}-${name}.png`);
  }

  // Literal file names written by any other spec.
  for (const m of text.matchAll(/['"`]((?:[\w.-]+\/)*[\w.-]+\.png)['"`]/g)) {
    understood = true;
    const name = m[1].split('/').pop();
    if (!name.includes('${')) expected.add(name);
  }
  if (!understood && /__screenshots__|\.screenshot\(\s*\{\s*path/.test(text)) {
    warnings.push(`${file} writes screenshots in a way this script does not understand`);
  }
}

if (expected.size === 0) {
  console.error('screenshots-dedupe: found no expected files; refusing to delete anything.');
  process.exit(2);
}

let stale = [];
try {
  stale = readdirSync(shots).filter((f) => !f.startsWith('.') && statSync(join(shots, f)).isFile() && !expected.has(f));
} catch {
  console.log('screenshots-dedupe: no screenshot folder, nothing to do.');
  process.exit(0);
}

let freed = 0;
for (const f of stale) {
  const path = join(shots, f);
  freed += statSync(path).size;
  if (!dryRun) rmSync(path);
}

for (const w of warnings) console.warn(`warning: ${w}`);
const kb = (freed / 1024).toFixed(0);
if (stale.length === 0) {
  console.log(`screenshots-dedupe: ${expected.size} expected files, no stale ones.`);
} else {
  console.log(`screenshots-dedupe: ${dryRun ? 'would remove' : 'removed'} ${stale.length} stale file(s), ${kb} KB:`);
  for (const f of stale) console.log(`  ${f}`);
}
if (check && stale.length > 0) process.exit(1);
